// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testRegression_property() public {
        address target = address(0x1234);
        uint depositAmount = 1 ether;
        uint sendValue = 0.5 ether;

        vm.deal(address(this), depositAmount);
        (bool success, ) = address(c).call{value: depositAmount}("");
        require(success);

        vm.prank(c.owner());
        c.sendMoney(target, sendValue, "");

        assertEq(address(c).balance, depositAmount - sendValue);
    }
}
